script:
Get-Service -Name wuauserv, bits, cryptsvc | Select-Object Name, Status, StartType
Write-Host 'Checking CBS Log for missing package references...'
if (Test-Path 'C:\Windows\Logs\CBS\CBS.log') {
    Select-String -Path 'C:\Windows\Logs\CBS\CBS.log' -Pattern '0x800f0831' -Context 0,2 | Select-Object -First 5
}

$paths = @('C:\Windows\SoftwareDistribution', 'C:\Windows\System32\catroot2')
foreach ($path in $paths) {
    if (Test-Path $path) {
        $acl = Get-Acl -Path $path
        [PSCustomObject]@{ Path = $path; Owner = $acl.Owner; AccessToString = $acl.AccessToString.Substring(0, [Math]::Min(100, $acl.AccessToString.Length)) }
    }
}

Get-Service -Name "WinDefend", "SecurityHealthService", "wscsvc" | Select-Object Name, Status, StartType
Write-Host "Defender 보안 정의 초기화 수행 중..." -ForegroundColor Green
if (Test-Path "C:\Program Files\Windows Defender\MpCmdRun.exe") {
    Start-Process -FilePath "C:\Program Files\Windows Defender\MpCmdRun.exe" -ArgumentList "-RemoveDefinitions -All" -Wait -WindowStyle Hidden
    Start-Process -FilePath "C:\Program Files\Windows Defender\MpCmdRun.exe" -ArgumentList "-SignatureUpdate" -Wait -WindowStyle Hidden
}

Stop-Service -Name wuauserv, bits, WinDefend -Force -ErrorAction SilentlyContinue
$defPath = "C:\ProgramData\Microsoft\Windows Defender\Definition Updates"
if (Test-Path $defPath) {
    Get-ChildItem -Path $defPath -Recurse | Remove-Item -Force -Recurse -ErrorAction SilentlyContinue
}
Start-Service -Name bits, wuauserv, WinDefend -ErrorAction SilentlyContinue
if (Test-Path "C:\Program Files\Windows Defender\MpCmdRun.exe") {
    Start-Process -FilePath "C:\Program Files\Windows Defender\MpCmdRun.exe" -ArgumentList "-SignatureUpdate" -NoNewWindow
}
